<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Professor');
$id_professor=$_SESSION['id_usuario'];$id_turma=intval($_GET['turma']??$_POST['turma']??0);$id_disciplina=intval($_GET['disciplina']??$_POST['disciplina']??0);
$turmas=[];$stmt=$conexao->prepare('SELECT DISTINCT t.id_turma,t.nome FROM turma t JOIN turma_disciplina td ON td.id_turma=t.id_turma WHERE td.id_professor=? ORDER BY t.nome');$stmt->bind_param('i',$id_professor);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$turmas[]=$row;}$stmt->close();if($id_turma<=0&&count($turmas)===1)$id_turma=(int)$turmas[0]['id_turma'];if($id_turma>0&&!array_filter($turmas,fn($row)=>(int)$row['id_turma']===$id_turma))$id_turma=0;
$disciplinas=[];if($id_turma>0){$stmt=$conexao->prepare('SELECT DISTINCT d.id_disciplina,d.nome FROM disciplina d JOIN turma_disciplina td ON td.id_disciplina=d.id_disciplina WHERE td.id_turma=? AND td.id_professor=? ORDER BY d.nome');$stmt->bind_param('ii',$id_turma,$id_professor);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$disciplinas[]=$row;}$stmt->close();}if($id_disciplina<=0&&count($disciplinas)===1)$id_disciplina=(int)$disciplinas[0]['id_disciplina'];if($id_disciplina>0&&!array_filter($disciplinas,fn($row)=>(int)$row['id_disciplina']===$id_disciplina))$id_disciplina=0;
$alunos_freq=[];$turma_nome='';$disciplina_nome='';if($id_turma>0&&$id_disciplina>0){$stmt=$conexao->prepare('SELECT td.id_turma_disciplina,t.nome AS turma_nome,d.nome AS disciplina_nome FROM turma_disciplina td JOIN turma t ON t.id_turma=td.id_turma JOIN disciplina d ON d.id_disciplina=td.id_disciplina WHERE td.id_turma=? AND td.id_disciplina=? AND td.id_professor=?');$stmt->bind_param('iii',$id_turma,$id_disciplina,$id_professor);$stmt->execute();$vinculo=$stmt->get_result()->fetch_assoc();$stmt->close();if($vinculo){$turma_nome=$vinculo['turma_nome'];$disciplina_nome=$vinculo['disciplina_nome'];$id_turma_disciplina=(int)$vinculo['id_turma_disciplina'];$stmt=$conexao->prepare('SELECT m.id_matricula,m.rm,u.nome,COALESCE(SUM(CASE WHEN f.presente=1 THEN 1 ELSE 0 END),0) AS presentes,COUNT(f.id_frequencia) AS total FROM matricula m JOIN usuario u ON u.id_usuario=m.id_aluno LEFT JOIN frequencia f ON f.id_matricula=m.id_matricula AND f.id_turma_disciplina=? WHERE m.id_turma=? GROUP BY m.id_matricula,m.rm,u.nome ORDER BY u.nome');$stmt->bind_param('ii',$id_turma_disciplina,$id_turma);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$total=(int)$row['total'];$presentes=(int)$row['presentes'];$freq=$total>0?round($presentes/$total*100):0;$alunos_freq[]=['rm'=>$row['rm'],'nome'=>$row['nome'],'presentes'=>$presentes,'faltas'=>$total-$presentes,'total'=>$total,'frequencia'=>$freq,'situacao'=>$freq<75?'Risco':($freq<90?'Atenção':'Regular'),'classe'=>$freq<75?'vermelho':($freq<90?'amarelo':'verde')];}$stmt->close();}}
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Professor | Presença</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f4f7fb;color:#1f2937}main{max-width:1180px;margin:32px auto;padding:0 20px 40px}.topo{background:linear-gradient(135deg,#1f3b65,#4568a8);color:#fff;border-radius:18px;padding:30px 28px;margin-bottom:26px}.topo h1{margin:0 0 4px;font-size:2rem}.topo p{margin:0;font-size:.9rem;opacity:.8}.panel{background:#fff;border-radius:18px;padding:22px;border:1px solid #e5ebf6;box-shadow:0 10px 22px rgba(15,23,42,.04);margin-bottom:22px}.panel h2{margin-top:0;color:#133b6d}.filtros{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap}.filtros label{font-size:.78rem;font-weight:bold;display:block;margin-bottom:4px}.filtros select,.filtros input{border:1px solid #dfe9f6;border-radius:8px;padding:8px 12px;font-size:.84rem}.btn{background:#183f73;color:#fff;border:0;border-radius:8px;padding:8px 16px;font-weight:bold;cursor:pointer}table{width:100%;border-collapse:collapse;font-size:.875rem}th,td{text-align:left;padding:12px;border-bottom:1px solid #edf2f9}th{font-size:.75rem;color:#6b7280;text-transform:uppercase}.badge{padding:4px 10px;border-radius:999px;font-size:.75rem;font-weight:bold}.verde{background:#eaf7ef;color:#157c3d}.amarelo{background:#fff7e8;color:#996000}.vermelho{background:#fee2e2;color:#991b1b}</style></head><body><?php include '../../includes/menu_professor.php';?><main><section class="topo"><h1>Presença dos Alunos</h1><p>Acompanhe a frequência por turma e disciplina</p></section><section class="panel"><form method="GET" class="filtros"><div><label>Turma</label><?php if(count($turmas)===1):?><input type="hidden" name="turma" value="<?php echo $id_turma;?>"><strong><?php echo htmlspecialchars($turmas[0]['nome']);?></strong><?php else:?><select name="turma" onchange="this.form.submit()"><option value="">Selecione uma turma</option><?php foreach($turmas as $turma):?><option value="<?php echo $turma['id_turma'];?>" <?php echo $id_turma==$turma['id_turma']?'selected':'';?>><?php echo htmlspecialchars($turma['nome']);?></option><?php endforeach;?></select><?php endif;?></div><div><label>Disciplina</label><?php if(count($disciplinas)===1):?><input type="hidden" name="disciplina" value="<?php echo $id_disciplina;?>"><strong><?php echo htmlspecialchars($disciplinas[0]['nome']);?></strong><?php else:?><select name="disciplina"><option value="">Selecione uma disciplina</option><?php foreach($disciplinas as $disc):?><option value="<?php echo $disc['id_disciplina'];?>" <?php echo $id_disciplina==$disc['id_disciplina']?'selected':'';?>><?php echo htmlspecialchars($disc['nome']);?></option><?php endforeach;?></select><?php endif;?></div><button class="btn" type="submit">Buscar</button></form><?php if($id_turma>0&&$id_disciplina>0):?><h2>Frequência - <?php echo htmlspecialchars($turma_nome.' · '.$disciplina_nome);?></h2><?php if($alunos_freq):?><table><thead><tr><th>RM</th><th>Aluno</th><th>Presenças</th><th>Faltas</th><th>Total</th><th>Frequência</th><th>Situação</th></tr></thead><tbody><?php foreach($alunos_freq as $aluno):?><tr><td><?php echo htmlspecialchars($aluno['rm']);?></td><td><?php echo htmlspecialchars($aluno['nome']);?></td><td><?php echo $aluno['presentes'];?></td><td><?php echo $aluno['faltas'];?></td><td><?php echo $aluno['total'];?></td><td><?php echo $aluno['frequencia'];?>%</td><td><span class="badge <?php echo $aluno['classe'];?>"><?php echo $aluno['situacao'];?></span></td></tr><?php endforeach;?></tbody></table><?php else:?><p style="color:#666">Nenhum aluno ou registro de frequência encontrado.</p><?php endif;?><?php endif;?></section></main></body></html>
